package it.gestionechiavi.mezzi
import android.graphics.*;import android.os.Bundle;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import okhttp3.*;import okhttp3.MediaType.Companion.toMediaType;import okhttp3.RequestBody.Companion.toRequestBody;import java.io.*
class PhotoActivity:AppCompatActivity(){private var bitmap:Bitmap?=null;private val camera=registerForActivityResult(ActivityResultContracts.TakePicturePreview()){b->if(b!=null){bitmap=b;findViewById<android.widget.ImageView>(R.id.preview).setImageBitmap(b);findViewById<android.widget.Button>(R.id.upload).isEnabled=true}};override fun onCreate(b:Bundle?){super.onCreate(b);setContentView(R.layout.activity_photo);findViewById<android.widget.Button>(R.id.take).setOnClickListener{camera.launch(null)};findViewById<android.widget.Button>(R.id.upload).setOnClickListener{upload()}};private fun upload(){val src=bitmap?:return;show("Compressione e caricamento…");val scale=minOf(1f,1600f/maxOf(src.width,src.height));val b=if(scale<1)Bitmap.createScaledBitmap(src,(src.width*scale).toInt(),(src.height*scale).toInt(),true)else src;val out=ByteArrayOutputStream();var q=78;b.compress(Bitmap.CompressFormat.JPEG,q,out);while(out.size()>900*1024&&q>50){q-=8;out.reset();b.compress(Bitmap.CompressFormat.JPEG,q,out)};val body=MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart("assignment_id",intent.getStringExtra("assignment_id").orEmpty()).addFormDataPart("driver_code",intent.getIntExtra("driver_code",0).toString()).addFormDataPart("note",findViewById<android.widget.EditText>(R.id.note).text.toString()).addFormDataPart("photo","mezzo.jpg",out.toByteArray().toRequestBody("image/jpeg".toMediaType())).build();Api.client.newCall(Request.Builder().url(Api.BASE+"/vehicle-photo").post(body).build()).enqueue(object:Callback{override fun onFailure(c:Call,e:IOException)=show("Errore rete");override fun onResponse(c:Call,r:Response)=show(if(r.isSuccessful)"Foto compressa e salvata"else"Errore caricamento: ${r.code}")})};private fun show(s:String)=runOnUiThread{findViewById<android.widget.TextView>(R.id.msg).text=s}}
